    // tech (it is playback plumbing, not content). This also keeps
    // it out of the page's landmark/region tree.
    format!(
        "<div{data_id} aria-hidden=\"true\" style=\"{MEDIA_CONTROLLER_SHELL_STYLE}\">{media}</div>"
