        break;
      }
      case PROP_FONT_WEIGHT: {
        const weight = f32FromBits(attr.value);
        if (weight > 0) {
          css += `font-weight:${weight};`;
        }
        break;
      }
      case PROP_COLOR:
        css += `color:${argbToRgba(attr.value)};`;
        break;
      case PROP_FONT_STYLE:
        if (f32FromBits(attr.value) === 1) {
          css += "font-style:italic;";
