   WINDOW_TITLE,
 } from "../src/constants";
 import { buildBatch, stringEntry } from "./plpl.test";

 const f32bits = (v: number): number => new Uint32Array(new Float32Array([v]).buffer)[0] ?? 0;

 beforeEach(() => {
   document.head.querySelectorAll("style[data-pathland-tokens]").forEach((s) => s.remove());
 });

 function renderer(): DomRenderer {
   return { byId: new Map<number, Node>() };
 }

 /** The lazy icon resolver must not hit the network in these tests. */
 function noNetworkIcons() {
   vi.stubGlobal("fetch", async () => ({ ok: false, text: async () => "" }));
 }

 afterEach(() => {
   vi.useRealTimers();
   vi.unstubAllGlobals();
 });

 /** Drop an SSR-style embedded glyph into the document (what a hydrated page carries). */
 function seedGlyph(name: string, inner: string): void {
   const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
   svg.setAttribute("class", "pathland-icon");
   svg.setAttribute("data-pathland-icon", name);
   svg.innerHTML = inner;
   document.body.appendChild(svg);
 }

 describe("media autoplay policy", () => {
   const flush = () => new Promise((resolve) => setTimeout(resolve, 0));

   /** A playback element hydrated from the SSR HTML: the controller node is the
    *  `data-pathland-id` container, and the inner `<video data-pathland-media>`
    *  is its control-less playback element (the real SSR shape). Wired through the
    *  **media element** so the report-id derivation is exercised. */
   function hydratedMedia(id = 1): { media: HTMLMediaElement; element: HTMLElement; r: DomRenderer } {
     const wrapper = document.createElement("div");
     wrapper.setAttribute("data-pathland-id", String(id));
     const media = document.createElement("video");
     media.setAttribute("data-pathland-media", "");
     media.setAttribute("src", "/_pathland/assets/audio/track1.mp3");
     wrapper.appendChild(media);
     document.body.appendChild(wrapper);
     const r = renderer();
     r.byId.set(id, wrapper);
     setupMediaElement(media, r);
     return { media, element: wrapper, r };
   }

   it("keys a controller's media reports to its node id, not 0", async () => {
     // The controller's `<video>` carries no id of its own — reports must resolve
     // the id from the nearest `[data-pathland-id]` ancestor (the controller node),
     // or every MEDIA_TIME_UPDATED goes out as target=0 and progress stalls.
     const wrapper = document.createElement("div");
     wrapper.setAttribute("data-pathland-id", "241");
     const media = document.createElement("video");
     media.setAttribute("data-pathland-media", "");
     media.setAttribute("src", "/_pathland/assets/audio/track1.mp3");
     Object.defineProperty(media, "duration", { value: 120, configurable: true });
     wrapper.appendChild(media);
     document.body.appendChild(wrapper);

     const sent: Uint8Array[] = [];
     const r: DomRenderer = { byId: new Map(), onMediaEvent: (b) => sent.push(b) };
     setupMediaElement(media, r);

     media.dispatchEvent(new Event("durationchange"));
     expect(sent.length).toBe(1);
     // The EVENT opcode's target (A) is the 4th field of the first opcode.
     const view = new DataView(sent[0]!.buffer, sent[0]!.byteOffset);
     const opcodePos = 16; // HEADER_SIZE
     expect(view.getUint32(opcodePos + 4, true)).toBe(241);
   });

   it("retries a play() the autoplay policy blocked, on the next gesture", async () => {
     const media = document.createElement("video");
     document.body.appendChild(media);
     const play = vi
       .fn()
       .mockImplementationOnce(() =>
         Promise.reject(Object.assign(new Error("blocked"), { name: "NotAllowedError" })),
       )
       .mockImplementation(() => Promise.resolve());
     media.play = play as unknown as HTMLMediaElement["play"];

     // The server-driven play arrives outside a gesture: the browser blocks it.
     playMedia(media);
     expect(play).toHaveBeenCalledTimes(1);
     await flush();

     // The next trusted gesture replays it…
     retryPendingPlay();
     expect(play).toHaveBeenCalledTimes(2);
     // …and it is no longer pending.
     retryPendingPlay();
     expect(play).toHaveBeenCalledTimes(2);
   });

   it("logs a non-autoplay play() rejection instead of swallowing it", async () => {
     const media = document.createElement("video");
     document.body.appendChild(media);
     const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
     media.play = vi.fn(() =>
       Promise.reject(Object.assign(new Error("bad"), { name: "NotSupportedError" })),
     ) as unknown as HTMLMediaElement["play"];

     playMedia(media);
     await flush();
     expect(warn).toHaveBeenCalled();
     warn.mockRestore();
   });

   it("unlocks the playback element muted inside a gesture, then restores the mute", async () => {
     const { media } = hydratedMedia();
     let mutedDuringPlay: boolean | null = null;
     media.play = vi.fn(() => {
       mutedDuringPlay = media.muted;
       return Promise.resolve();
     }) as unknown as HTMLMediaElement["play"];

     unlockMedia();
     expect(mutedDuringPlay).toBe(true); // played muted (always permitted)
     await flush();
     expect(media.muted).toBe(false); // mute state restored
   });

   it("does not unlock while the app already wants the element playing", async () => {
     const { media, r } = hydratedMedia();
     const play = vi.fn(() => Promise.resolve());
     media.play = play as unknown as HTMLMediaElement["play"];

     // The app requested playing: a PLAYBACK_STATE apply sets `state.playing`.
     applyBatch(
       parseBatch(
         buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1, ((VAL_U8 << 16) | PROP_PLAYBACK_STATE) >>> 0, 1]], stringEntry("")),
       ),
       r,
     );
     expect(play).toHaveBeenCalledTimes(1); // the app's own play

     unlockMedia();
     await flush();
     expect(play).toHaveBeenCalledTimes(1); // the unlock leaves it alone
   });
 });

 describe("applyBatch · media", () => {
   it("seeks only on a meaningful MEDIA_POSITION change (no echo interruption)", () => {
     const wrapper = document.createElement("div");
     wrapper.className = "pathland-media";
     wrapper.setAttribute("data-pathland-id", "1");
     wrapper.setAttribute("data-pathland-media", "");
     const audio = document.createElement("audio");
     wrapper.appendChild(audio);
     document.body.appendChild(wrapper);
     const r = renderer();
     r.byId.set(1, wrapper);

     // A near-identical position (a timeupdate echo) must NOT seek the element —
     // even when the network delay means the element's currentTime has advanced
     // past the reported position (the guard compares against the last-reported
     // position, not currentTime).
     setupMediaElement(wrapper, r);
     audio.currentTime = 3.5;
     __setMediaLastReported(audio, 3);
     applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1,
       ((VAL_F32 << 16) | PROP_MEDIA_POSITION) >>> 0, f32bits(3.1)]], stringEntry(""))), r);
     expect(audio.currentTime).toBe(3.5);

     // A real seek (a user drag) does.
     applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1,
       ((VAL_F32 << 16) | PROP_MEDIA_POSITION) >>> 0, f32bits(120)]], stringEntry(""))), r);
     expect(audio.currentTime).toBe(120);
   });

   it("resumes playback when the source changes while playing (a skip keeps playing)", () => {
     const wrapper = document.createElement("div");
     wrapper.className = "pathland-media";
     wrapper.setAttribute("data-pathland-id", "1");
     wrapper.setAttribute("data-pathland-media", "");
     const audio = document.createElement("audio");
     wrapper.appendChild(audio);
     document.body.appendChild(wrapper);
     const r = renderer();
     r.byId.set(1, wrapper);

     // App requests playing -> the element plays.
     applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1,
       ((VAL_U32 << 16) | PROP_PLAYBACK_STATE) >>> 0, 1]], stringEntry(""))), r);
     expect(audio.paused).toBe(false);

     // A source change (skip/auto-advance) resets the element to paused...
     audio.pause();
     // ...and applying the new source resumes playback.
     applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1,
       ((VAL_STRING << 16) | PROP_MEDIA_SOURCE) >>> 0, 0]], stringEntry("/track2.mp3"))), r);
     expect(audio.paused).toBe(false);
   });

   it("binds a VIDEO surface that precedes its controller (order-independent)", () => {
     // The surface is emitted first: its MEDIA_CONTROLLER_ID references a
     // controller node that does not exist yet. Binding must not depend on
     // emission order — a later MEDIA_SOURCE on the controller completes it
     // (spec/MEDIA.md).
     const surface = document.createElement("div");
     surface.setAttribute("data-pathland-id", "2");
     const surfaceVideo = document.createElement("video");
     surfaceVideo.setAttribute("data-pathland-media", "");
     surface.appendChild(surfaceVideo);
     document.body.appendChild(surface);
     const r = renderer();
     r.byId.set(2, surface);

     // The surface binds to controller 1 (which is not in the tree yet).
     applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 2,
       ((VAL_U32 << 16) | PROP_MEDIA_CONTROLLER_ID) >>> 0, 1]], stringEntry(""))), r);
     expect(surfaceVideo.src).toBe("");

     // The controller arrives afterwards with its resource.
     const controller = document.createElement("div");
     controller.setAttribute("data-pathland-id", "1");
     controller.setAttribute("data-pathland-media", "");
     const controllerVideo = document.createElement("video");
     controllerVideo.setAttribute("data-pathland-media", "");
     controller.appendChild(controllerVideo);
     document.body.appendChild(controller);
     r.byId.set(1, controller);

     applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1,
       ((VAL_STRING << 16) | PROP_MEDIA_SOURCE) >>> 0, 0]], stringEntry("/track9.mp3"))), r);

     // The surface adopted the resource; the controller element carries no audio.
     expect(surfaceVideo.getAttribute("src")).toContain("track9.mp3");
     expect(controllerVideo.muted).toBe(true);
   });

   it("reports MEDIA_TIME_UPDATED at ~30/s (a 33 ms position sampler)", () => {
     vi.useFakeTimers();
     const wrapper = document.createElement("div");
     wrapper.className = "pathland-media";
     wrapper.setAttribute("data-pathland-id", "1");
     wrapper.setAttribute("data-pathland-media", "");
     const audio = document.createElement("audio");
     wrapper.appendChild(audio);
     document.body.appendChild(wrapper);
     const sent: Uint8Array[] = [];
     const r = renderer();
     r.byId.set(1, wrapper);
     r.onMediaEvent = (batch: Uint8Array) => sent.push(batch);

     // Wire the media element and start "playing" (paused=false for the gate).
     applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1,
       ((VAL_U32 << 16) | PROP_PLAYBACK_STATE) >>> 0, 1]], stringEntry(""))), r);

     // The first sample establishes the baseline report (last 0 → 0.04 s).
     audio.currentTime = 0.04;
     vi.advanceTimersByTime(40);
     expect(sent).toHaveLength(1);

     // A sub-step advance (< ~33 ms of progress) is dropped on the next tick.
     audio.currentTime = 0.05;
     vi.advanceTimersByTime(40);
     expect(sent).toHaveLength(1);

     // A real ~1/30 s step per tick reports again (~30 samples/s).
     audio.currentTime = 0.10;
     vi.advanceTimersByTime(40);
     expect(sent).toHaveLength(2);
   });

   it("removing a media node clears its 30 Hz position sampler", () => {
     vi.useFakeTimers();
     const wrapper = document.createElement("div");
     wrapper.className = "pathland-media";
     wrapper.setAttribute("data-pathland-id", "1");
     wrapper.setAttribute("data-pathland-media", "");
     const audio = document.createElement("audio");
     wrapper.appendChild(audio);
     document.body.appendChild(wrapper);
     const sent: Uint8Array[] = [];
     const r = renderer();
     r.byId.set(1, wrapper);
     r.onMediaEvent = (batch: Uint8Array) => sent.push(batch);
     applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1,
       ((VAL_U32 << 16) | PROP_PLAYBACK_STATE) >>> 0, 1]], stringEntry(""))), r);

     // Delete the node: the sampler must stop (no reports after deletion,
     // even as the position advances and time passes).
     applyBatch(parseBatch(buildBatch([[CAT_TREE, CMD_DELETE_NODE, 0, 1]])), r);
     audio.currentTime = 5;
     vi.advanceTimersByTime(120);
     expect(sent).toHaveLength(0);
   });
 });

 describe("applyBatch · STYLE", () => {
   it("applies SET_TEXT to a hydrated span", () => {
     const span = document.createElement("span");
     span.setAttribute("data-pathland-id", "1");
     const r = renderer();
     r.byId.set(1, span);
     const batch = parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_TEXT, 0, 1, 0, 0]], stringEntry("hi!")));
     applyBatch(batch, r);
     expect(span.textContent).toBe("hi!");
   });

   it("applies SET_ATTRIBUTED_TEXT as spans and links", () => {
     const span = document.createElement("span");
     span.setAttribute("data-pathland-id", "1");
     const r = renderer();
     r.byId.set(1, span);

     const text = new TextEncoder().encode("Hi");
     const url = new TextEncoder().encode("x");
     const payload = new Uint8Array(4 + text.length + 4 + 12 + 8 + 4 + 12 + url.length);
     const view = new DataView(payload.buffer);
     let p = 0;
     view.setUint32(p, text.length, true); p += 4;
     payload.set(text, p); p += text.length;
     view.setUint32(p, 1, true); p += 4;
     view.setUint32(p, 0, true); p += 4;
     view.setUint32(p, 2, true); p += 4;
     view.setUint32(p, 1, true); p += 4;
     view.setUint16(p, PROP_FONT_WEIGHT, true); p += 2;
     view.setUint8(p, VAL_F32); p += 1;
     view.setUint8(p, 0); p += 1;
     view.setUint32(p, f32bits(700), true); p += 4;
     view.setUint32(p, 1, true); p += 4;
     view.setUint32(p, 1, true); p += 4;
     view.setUint32(p, 2, true); p += 4;
     view.setUint32(p, url.length, true); p += 4;
     payload.set(url, p);

     const strings = new Uint8Array(4 + payload.length);
     new DataView(strings.buffer).setUint32(0, payload.length, true);
     strings.set(payload, 4);

     applyBatch(
       parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_ATTRIBUTED_TEXT, 0, 1, 0, 0]], strings)),
       r,
     );
     expect(span.textContent).toBe("Hi");
     expect(span.querySelector("span")?.getAttribute("style")).toContain("font-weight:700");
     expect(span.querySelector("a")?.getAttribute("href")).toBe("x");
   });

   it("does not render an unsafe javascript: attributed link", () => {
     const span = document.createElement("span");
     span.setAttribute("data-pathland-id", "1");
     const r = renderer();
     r.byId.set(1, span);

     const text = new TextEncoder().encode("Hi");
     const url = new TextEncoder().encode("javascript:alert(1)");
     const payload = new Uint8Array(4 + text.length + 4 + 4 + 12 + url.length);
     const view = new DataView(payload.buffer);
     let p = 0;
     view.setUint32(p, text.length, true); p += 4;
     payload.set(text, p); p += text.length;
     view.setUint32(p, 0, true); p += 4; // runCount
     view.setUint32(p, 1, true); p += 4; // linkCount
     view.setUint32(p, 0, true); p += 4; // start
     view.setUint32(p, 2, true); p += 4; // end
     view.setUint32(p, url.length, true); p += 4;
     payload.set(url, p);

     const strings = new Uint8Array(4 + payload.length);
     new DataView(strings.buffer).setUint32(0, payload.length, true);
     strings.set(payload, 4);

     applyBatch(
       parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_ATTRIBUTED_TEXT, 0, 1, 0, 0]], strings)),
       r,
     );
     expect(span.textContent).toBe("Hi");
     expect(span.querySelector("a")).toBeNull();
   });

   it("does not apply an unsafe javascript: image source", () => {
     const img = document.createElement("img");
     img.setAttribute("data-pathland-id", "1");
     const r = renderer();
     r.byId.set(1, img);
     applyBatch(
       parseBatch(buildBatch([
         [CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1, (VAL_STRING << 16) | PROP_IMAGE_SOURCE, 0],
       ], stringEntry("javascript:alert(1)"))),
       r,
     );
     expect(img.getAttribute("src")).toBeNull();
   });

   it("rejects an unknown value type before mutating the DOM", () => {
     const span = document.createElement("span");
     span.setAttribute("data-pathland-id", "1");
     span.textContent = "keep";
     const r = renderer();
     r.byId.set(1, span);
     expect(() =>
       applyBatch(
         parseBatch(buildBatch([
           [CAT_PARAMETER, CMD_SET_TEXT, 0, 1, 0, 0],
           [CAT_PARAMETER, CMD_SET_PROPERTY, 0, 1, (0x7f << 16) | PROP_TEXT, 0],
         ], stringEntry("changed"))),
         r,
       ),
     ).toThrow(/unknown value type/);
     expect(span.textContent).toBe("keep");
   });

   it("applies SET_TEXT to a text field's input", () => {
     const tf = document.createElement("label");
     tf.className = "pathland-textfield";
     const input = document.createElement("input");
     input.type = "text";
     tf.appendChild(input);
     const r = renderer();
     r.byId.set(5, tf);
     applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, CMD_SET_TEXT, 0, 5, 0, 0]], stringEntry("ab"))), r);
     expect(input.value).toBe("ab");
   });

   it("applies SELECTED to a toggle checkbox", () => {
     const toggle = document.createElement("label");
     toggle.className = "pathland-toggle";
     const box = document.createElement("input");
     box.type = "checkbox";
     toggle.appendChild(box);
     const r = renderer();
     r.byId.set(4, toggle);
     applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, 1, 0, 4, (0 << 16) | PROP_SELECTED, 1]])), r);
     expect(box.checked).toBe(true);
   });

   it("applies VALUE to a slider and updates the tokenized fill", () => {
     const slider = document.createElement("label");
     slider.className = "pathland-slider";
     const range = document.createElement("input");
     range.type = "range";
     range.min = "0";
     range.max = "1";
     slider.appendChild(range);
     const r = renderer();
     r.byId.set(6, slider);
     const bits = new Uint32Array(new Float32Array([0.75]).buffer)[0]!;
     applyBatch(parseBatch(buildBatch([[CAT_PARAMETER, 1, 0, 6, (0 << 16) | PROP_VALUE, bits]])), r);
     expect(range.value).toBe("0.75");
     expect(range.style.getPropertyValue("--pl-slider-fill")).toBe("75%");
   });

   it("suppresses VALUE while a slider is being dragged (in-flight)", () => {
     const slider = document.createElement("label");
     slider.className = "pathland-slider";
     const range = document.createElement("input");
     range.type = "range";
     range.min = "0";
     range.max = "1";
     range.value = "0.3";
     slider.appendChild(range);
     const r = renderer();
     r.byId.set(6, slider);
     const bits = new Uint32Array(new Float32Array([0.75]).buffer)[0]!;
     const batch = () =>
       parseBatch(buildBatch([[CAT_PARAMETER, 1, 0, 6, (0 << 16) | PROP_VALUE, bits]]));

     // While the drag is in flight the server echo must not move the thumb.
     markRangeInFlight(range);
     applyBatch(batch(), r);
     expect(range.value).toBe("0.3");
     expect(range.style.getPropertyValue("--pl-slider-fill")).toBe("30%");

     // On release, inbound VALUE applies again.
     clearInFlightRange();
     applyBatch(batch(), r);
     expect(range.value).toBe("0.75");
     expect(range.style.getPropertyValue("--pl-slider-fill")).toBe("75%");
   });

   it("recomputes the slider fill when MIN_VALUE/MAX_VALUE change", () => {
     const slider = document.createElement("label");
     slider.className = "pathland-slider";
     const range = document.createElement("input");
     range.type = "range";
     range.min = "0";
     range.max = "10";
     range.value = "5";
     slider.appendChild(range);
     const r = renderer();
     r.byId.set(6, slider);

     applyBatch(
       parseBatch(
         buildBatch([[CAT_PARAMETER, 1, 0, 6, (VAL_F32 << 16) | PROP_MAX_VALUE, f32bits(20)]]),
       ),
       r,
     );
     expect(range.style.getPropertyValue("--pl-slider-fill")).toBe("25%");

     applyBatch(
       parseBatch(
         buildBatch([[CAT_PARAMETER, 1, 0, 6, (VAL_F32 << 16) | PROP_MIN_VALUE, f32bits(5)]]),
       ),
       r,
     );
     expect(range.style.getPropertyValue("--pl-slider-fill")).toBe("0%");
   });
 });

