  // Fresh nodes (e.g. a ViewThatFits candidate swap) emit CREATE + properties
  // BEFORE the children. The label must stay an accessible name, not become a
  // text node that precedes the later-inserted icon.
  const r = renderer();
  applyBatch(
    parseBatch(
      buildBatch(
        [
